using Benefits.Domain;

namespace Benefits.Application.Employees;

/// <summary>
/// Persistence contract for employees. Uniqueness of <see cref="Employee.Email"/>
/// is enforced both by explicit existence checks and by a unique index in the
/// database, so <see cref="AddAsync"/> returns false when the database rejects
/// the insert as a duplicate.
/// </summary>
public interface IEmployeeRepository
{
    /// <summary>Inserts the employee; returns false if the email is already taken.</summary>
    Task<bool> AddAsync(Employee employee, CancellationToken cancellationToken = default);

    /// <summary>Returns true if an employee with this email already exists.</summary>
    Task<bool> EmailExistsAsync(string email, CancellationToken cancellationToken = default);
}

namespace Benefits.Application.Employees;

/// <summary>Why an add-starter request was rejected.</summary>
public enum AddStarterError
{
    None,
    MissingRequiredFields,
    InvalidEmail,
    DuplicateEmail,
}

namespace Benefits.Application.Employees;

/// <summary>Outcome of an add-starter use case.</summary>
public sealed record AddStarterResult(EmployeeDto? Employee, AddStarterError Error)
{
    public static AddStarterResult Success(EmployeeDto employee) => new(employee, AddStarterError.None);

    public static AddStarterResult Failure(AddStarterError error) => new(null, error);

    public bool IsSuccess => Error is AddStarterError.None && Employee is not null;
}

using Benefits.Domain;
using Microsoft.Extensions.Logging;

namespace Benefits.Application.Employees;

/// <summary>
/// Use case: add a new starter. Generates a GUID <see cref="Employee.EmployeeNo"/>,
/// validates the email, enforces email uniqueness (checked explicitly and backed
/// by a unique database index) and persists the employee.
/// </summary>
public interface IAddStarterService
{
    Task<AddStarterResult> AddStarterAsync(AddStarterRequest request, CancellationToken cancellationToken = default);
}

public sealed class AddStarterService(IEmployeeRepository repository, ILogger<AddStarterService> logger)
    : IAddStarterService
{
    public async Task<AddStarterResult> AddStarterAsync(AddStarterRequest request, CancellationToken cancellationToken = default)
    {
        var email = request.Email?.Trim();

        if (string.IsNullOrWhiteSpace(email))
        {
            logger.LogWarning("Starter not saved: required field 'Email' is missing.");
            return AddStarterResult.Failure(AddStarterError.MissingRequiredFields);
        }

        if (!IsValidEmail(email))
        {
            logger.LogWarning("Starter not saved: '{Email}' is not a valid email address.", email);
            return AddStarterResult.Failure(AddStarterError.InvalidEmail);
        }

        if (await repository.EmailExistsAsync(email, cancellationToken))
        {
            logger.LogWarning("Starter not saved: an employee with email '{Email}' already exists.", email);
            return AddStarterResult.Failure(AddStarterError.DuplicateEmail);
        }

        var employee = new Employee
        {
            EmployeeNo = Guid.NewGuid().ToString(),
            Email = email,
            Title = request.Title,
            Firstname = request.Firstname,
            Surname = request.Surname,
            Dob = request.Dob,
            Gender = request.Gender,
            Address = request.Address,
        };

        if (!await repository.AddAsync(employee, cancellationToken))
        {
            logger.LogWarning(
                "Starter not saved: the database rejected the insert because email '{Email}' is already in use.",
                email);
            return AddStarterResult.Failure(AddStarterError.DuplicateEmail);
        }

        logger.LogInformation(
            "Starter saved successfully. EmployeeNo={EmployeeNo}, Email={Email}, Name={Title} {Firstname} {Surname}.",
            employee.EmployeeNo, employee.Email, employee.Title, employee.Firstname, employee.Surname);

        return AddStarterResult.Success(ToDto(employee));
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            return new System.Net.Mail.MailAddress(email).Address == email;
        }
        catch (FormatException)
        {
            return false;
        }
        catch (ArgumentException)
        {
            return false;
        }
    }

    private static EmployeeDto ToDto(Employee employee) => new()
    {
        EmployeeNo = employee.EmployeeNo,
        Email = employee.Email,
        Title = employee.Title,
        Firstname = employee.Firstname,
        Surname = employee.Surname,
        Dob = employee.Dob,
        Gender = employee.Gender,
        Address = employee.Address,
    };
}

using Microsoft.Data.Sqlite;

namespace Benefits.Infrastructure;

/// <summary>
/// Owns the single open in-memory SQLite connection. SQLite keeps an in-memory
/// database alive only while at least one connection is open, so this instance
/// is registered as a singleton and holds the connection for the process lifetime.
/// </summary>
public sealed class EmployeeDatabase : IDisposable
{
    private readonly SqliteConnection _connection;

    public EmployeeDatabase()
    {
        _connection = new SqliteConnection("Data Source=:memory:");
        _connection.Open();

        CreateSchema();
    }

    internal SqliteConnection Connection => _connection;

    private void CreateSchema()
    {
        using var command = _connection.CreateCommand();
        command.CommandText = """
            CREATE TABLE IF NOT EXISTS Employees (
                EmployeeNo TEXT NOT NULL PRIMARY KEY,
                Title      TEXT,
                Firstname  TEXT,
                Surname    TEXT,
                Dob        TEXT,
                Gender     TEXT,
                Email      TEXT NOT NULL,
                Address    TEXT
            );

            CREATE UNIQUE INDEX IF NOT EXISTS IX_Employees_Email
                ON Employees (Email);
            """;
        command.ExecuteNonQuery();
    }

    public void Dispose() => _connection.Dispose();
}

