Now Api: naming policy + AddJsonOptions in Program. Create `src/Benefits.Api/Json/TitleCaseEnumNamingPolicy.cs`. Naming policy: convert Pascal Case "PreferNotToSay" → "Prefer not to say". Implementation:

```csharp
using System.Text.Json;
namespace Benefits.Api.Json;

/// <summary>
/// Converts enum member names to title-case display strings with spaces so that
/// enums read naturally over the wire, e.g. "PreferNotToSay" becomes
/// "Prefer not to say". The same conversion is applied when reading, which keeps
/// deserialization aligned with these wire names.
/// </summary>
public sealed class TitleCaseEnumNamingPolicy : JsonNamingPolicy
{
    public override string ConvertName(string name)
    {
        var sb = new StringBuilder(name.Length + 4);
        for (var i = 0; i < name.Length; i++)
        {
            var c = name[i];
            if (i > 0 && char.IsUpper(c))
            {
                sb.Append(' ');
                sb.Append(char.ToLowerInvariant(c));
            }
            else
            {
                sb.Append(c);
            }
        }
        return sb.ToString();
    }
}
```

