        "Starter saved successfully. EmployeeNo={EmployeeNo}, Email={Email}, Name={Firstname} {Surname}.",
        employee.EmployeeNo, employee.Email, employee.Firstname, employee.Surname);

    return AddStarterResult.Success(ToDto(employee));
}

