+namespace Benefits.Application.Employees;
+
+/// <summary>
+/// Field-level rules shared by the add and update use cases: required
+/// fields and email format. Uniqueness is not a field-level concern; it
+/// lives with the use cases and is backed by the repository/unique index.
+/// </summary>
+internal static class EmployeeValidation
+{
+    public static List<string> GetMissingRequiredFields(string? email, string? firstname, string? surname)
+    {
+        var missing = new List<string>(3);
+
+        if (string.IsNullOrWhiteSpace(email))
+        {
+            missing.Add("Email");
+        }
+
+        if (string.IsNullOrWhiteSpace(firstname))
+        {
+            missing.Add("Firstname");
+        }
+
+        if (string.IsNullOrWhiteSpace(surname))
+        {
+            missing.Add("Surname");
+        }
+
+        return missing;
+    }
+
+    public static bool IsValidEmail(string email)
+    {
+        try
+        {
+            return new System.Net.Mail.MailAddress(email).Address == email;
+        }
+        catch (FormatException)
+        {
+            return false;
+        }
+        catch (ArgumentException)
+        {
+            return false;
+        }
+    }
+}

