 /// <summary>
 /// In-memory fake used by unit tests: behaves like the unique-index database
 /// without requiring SQLite.
 /// </summary>
 public sealed class FakeEmployeeRepository : IEmployeeRepository
 {
     public List<Employee> Saved { get; } = [];

     private readonly HashSet<string> _emails = new(StringComparer.OrdinalIgnoreCase);

     private readonly HashSet<string> _employeeNos = new(StringComparer.Ordinal);

     public Task<bool> AddAsync(Employee employee, CancellationToken cancellationToken = default)
     {
         if (!_employeeNos.Add(employee.EmployeeNo))
         {
             return Task.FromResult(false);
         }

         if (!_emails.Add(employee.Email))
         {
             _employeeNos.Remove(employee.EmployeeNo);
             return Task.FromResult(false);
         }

         Saved.Add(employee);
         return Task.FromResult(true);
     }

     public Task<bool> EmployeeNoExistsAsync(string employeeNo, CancellationToken cancellationToken = default)
     {
         return Task.FromResult(_employeeNos.Contains(employeeNo));
     }

     public Task<Employee?> GetByEmployeeNoAsync(string employeeNo, CancellationToken cancellationToken = default)
     {
         var employee = Saved.FirstOrDefault(e => e.EmployeeNo == employeeNo);
         return Task.FromResult<Employee?>(employee);
     }

     public Task<bool> DeleteByEmployeeNoAsync(string employeeNo, CancellationToken cancellationToken = default)
     {
         var employee = Saved.FirstOrDefault(e => e.EmployeeNo == employeeNo);

         if (employee is null)
         {
             return Task.FromResult(false);
         }

         Saved.Remove(employee);
         _emails.Remove(employee.Email);
         _employeeNos.Remove(employee.EmployeeNo);
         return Task.FromResult(true);
     }

+    public Task<Employee?> GetByEmailAsync(string email, CancellationToken cancellationToken = default)
+    {
+        var employee = Saved.FirstOrDefault(e => e.Email.Equals(email, StringComparison.OrdinalIgnoreCase));
+        return Task.FromResult<Employee?>(employee);
+    }
+
+    public Task<bool> UpdateAsync(Employee employee, CancellationToken cancellationToken = default)
+    {
+        var index = Saved.FindIndex(e => e.EmployeeNo == employee.EmployeeNo);
+
+        if (index < 0)
+        {
+            return Task.FromResult(false);
+        }
+
+        var duplicate = Saved.Any(e =>
+            e.Email.Equals(employee.Email, StringComparison.OrdinalIgnoreCase) &&
+            e.EmployeeNo != employee.EmployeeNo);
+
+        if (duplicate)
+        {
+            return Task.FromResult(false);
+        }
+
+        Saved[index] = employee;
+        return Task.FromResult(true);
+    }
+
     public Task<bool> EmailExistsAsync(string email, CancellationToken cancellationToken = default)
     {
         return Task.FromResult(_emails.Contains(email));
     }

     public Task<(IReadOnlyList<Employee> Items, int TotalCount)> ListAsync(
         int page,
         int pageSize,
         CancellationToken cancellationToken = default)
     {
         var items = Saved
             .OrderBy(e => e.Surname, StringComparer.Ordinal)
             .ThenBy(e => e.Firstname, StringComparer.Ordinal)
             .ThenBy(e => e.Email, StringComparer.Ordinal)
             .Skip((page - 1) * pageSize)
             .Take(pageSize)
             .ToList();

         return Task.FromResult(((IReadOnlyList<Employee>)items, Saved.Count));
     }
 }

