namespace Benefits.Application.Employees;

/// <summary>
/// Field-level rules shared by the add and update use cases: required
/// fields and email format. Uniqueness is not a field-level concern; it
/// lives with the use cases and is backed by the repository/unique index.
/// </summary>
internal static class EmployeeValidation
{
    public static List<string> GetMissingRequiredFields(string? email, string? firstname, string? surname)
    {
        var missing = new List<string>(3);

        if (string.IsNullOrWhiteSpace(email))
        {
            missing.Add("Email");
        }

        if (string.IsNullOrWhiteSpace(firstname))
        {
            missing.Add("Firstname");
        }

        if (string.IsNullOrWhiteSpace(surname))
        {
            missing.Add("Surname");
        }

        return missing;
    }

    public static bool IsValidEmail(string email)
    {
        try
        {
            return new System.Net.Mail.MailAddress(email).Address == email;
        }
        catch (FormatException)
        {
            return false;
        }
        catch (ArgumentException)
        {
            return false;
        }
    }
}

using Benefits.Domain;

namespace Benefits.Application.Employees;

/// <summary>
/// Request to update an existing employee's details. The employee number is
/// the identity of the resource and lives in the route only — it cannot be
/// changed through this endpoint. Required and format rules match add: email,
/// firstname and surname are required; dob must not be in the future; gender
/// accepts the same wire strings ("Male", "Prefer not to say", ...).
/// </summary>
public sealed record UpdateEmployeeRequest
{
    public string? Title { get; init; }
    public string? Firstname { get; init; }
    public string? Surname { get; init; }
    public DateOnly? Dob { get; init; }
    public string? Gender { get; init; }
    public string? Email { get; init; }
    public string? Address { get; init; }
}

namespace Benefits.Application.Employees;

/// <summary>Why an update-employee request was rejected.</summary>
public enum UpdateEmployeeError
{
    None,
    NotFound,
    MissingRequiredFields,
    InvalidEmail,
    InvalidGender,
    FutureDateOfBirth,
    DuplicateEmail,
}

namespace Benefits.Application.Employees;

/// <summary>Outcome of an update-employee use case.</summary>
public sealed record UpdateEmployeeResult(EmployeeDto? Employee, UpdateEmployeeError Error, string? Message = null)
{
    public static UpdateEmployeeResult Success(EmployeeDto employee) => new(employee, UpdateEmployeeError.None);

    public static UpdateEmployeeResult Failure(UpdateEmployeeError error, string? message = null) =>
        new(null, error, message);

    public bool IsSuccess => Error is UpdateEmployeeError.None && Employee is not null;
}

using Microsoft.Extensions.Logging;

namespace Benefits.Application.Employees;

/// <summary>
/// Use case: update an existing employee's editable fields (everything except
/// <see cref="Domain.Employee.EmployeeNo"/>, which identifies the resource and
/// cannot be changed). Validation rules match adding a starter, and email
/// uniqueness applies but never to the employee's own number.
/// </summary>
public interface IUpdateEmployeeService
{
    Task<UpdateEmployeeResult> UpdateEmployeeAsync(
        string employeeNo,
        UpdateEmployeeRequest request,
        CancellationToken cancellationToken = default);
}

public sealed class UpdateEmployeeService(IEmployeeRepository repository, ILogger<UpdateEmployeeService> logger)
    : IUpdateEmployeeService
{
    public async Task<UpdateEmployeeResult> UpdateEmployeeAsync(
        string employeeNo,
        UpdateEmployeeRequest request,
        CancellationToken cancellationToken = default)
    {
        var normalised = employeeNo.Trim();

        if (string.IsNullOrWhiteSpace(normalised))
        {
            logger.LogWarning("Employee update failed: employee number is empty.");
            return UpdateEmployeeResult.Failure(UpdateEmployeeError.NotFound);
        }

        var existing = await repository.GetByEmployeeNoAsync(normalised, cancellationToken);

        if (existing is null)
        {
            logger.LogWarning("Employee update failed: no employee with employee number '{EmployeeNo}' exists.", normalised);
            return UpdateEmployeeResult.Failure(UpdateEmployeeError.NotFound);
        }

        var missingFields = EmployeeValidation.GetMissingRequiredFields(request.Email, request.Firstname, request.Surname);

        if (missingFields.Count is not 0)
        {
            var missing = string.Join(", ", missingFields);
            var message = $"The following required fields are missing or empty: {missing}.";
            logger.LogWarning("Employee '{EmployeeNo}' not updated: {Message}", normalised, message);
            return UpdateEmployeeResult.Failure(UpdateEmployeeError.MissingRequiredFields, message);
        }

        var email = request.Email!.Trim();

        if (!EmployeeValidation.IsValidEmail(email))
        {
            var message = $"'{email}' is not a valid email address.";
            logger.LogWarning("Employee '{EmployeeNo}' not updated: {Message}", normalised, message);
            return UpdateEmployeeResult.Failure(UpdateEmployeeError.InvalidEmail, message);
        }

        Gender? gender = null;

        if (!string.IsNullOrWhiteSpace(request.Gender))
        {
            if (!GenderParser.TryParse(request.Gender, out var parsedGender))
            {
                var allowed = string.Join(", ", GenderParser.AllowedValues);
                var message =
                    $"'{request.Gender.Trim()}' is not a valid gender. Allowed values are: {allowed}.";
                logger.LogWarning("Employee '{EmployeeNo}' not updated: {Message}", normalised, message);
                return UpdateEmployeeResult.Failure(UpdateEmployeeError.InvalidGender, message);
            }

            gender = parsedGender;
        }

        if (request.Dob is { } dob && dob > DateOnly.FromDateTime(DateTime.UtcNow))
        {
            const string message = "Date of birth cannot be in the future.";
            logger.LogWarning("Employee '{EmployeeNo}' not updated: {Message} (DOB={Dob}).", normalised, message, dob);
            return UpdateEmployeeResult.Failure(UpdateEmployeeError.FutureDateOfBirth, message);
        }

        var otherWithEmail = await repository.GetByEmailAsync(email, cancellationToken);

        if (otherWithEmail is not null && otherWithEmail.EmployeeNo != normalised)
        {
            var message = $"An employee with email '{email}' already exists.";
            logger.LogWarning("Employee '{EmployeeNo}' not updated: {Message}", normalised, message);
            return UpdateEmployeeResult.Failure(UpdateEmployeeError.DuplicateEmail, message);
        }

        var updated = new Domain.Employee
        {
            // The employee number is captured from the route, never from the
            // request, so it is the one field an update cannot change.
            EmployeeNo = normalised,
            Email = email,
            Firstname = request.Firstname!.Trim(),
            Surname = request.Surname!.Trim(),
            Title = request.Title,
            Dob = request.Dob,
            Gender = gender,
            Address = request.Address,
        };

        if (!await repository.UpdateAsync(updated, cancellationToken))
        {
            logger.LogWarning(
                "Employee '{EmployeeNo}' not updated: the employee no longer exists.",
                normalised);
            return UpdateEmployeeResult.Failure(UpdateEmployeeError.NotFound);
        }

        logger.LogInformation(
            "Employee updated. EmployeeNo={EmployeeNo}, Email={Email}, Name={Firstname} {Surname}.",
            updated.EmployeeNo, updated.Email, updated.Firstname, updated.Surname);

        return UpdateEmployeeResult.Success(ToDto(updated));
    }

    private static EmployeeDto ToDto(Domain.Employee employee) => new()
    {
        EmployeeNo = employee.EmployeeNo,
        Email = employee.Email,
        Title = employee.Title,
        Firstname = employee.Firstname,
        Surname = employee.Surname,
        Dob = employee.Dob,
        Gender = employee.Gender,
        Address = employee.Address,
    };
}

