                     employee.EmployeeNo,
                     employee.Title,
                     employee.Firstname,
                     employee.Surname,
                     Dob = employee.Dob?.ToString("O"),
                     Gender = (int?)employee.Gender,
                     employee.Email,
                     employee.Address,
                 },
                 cancellationToken: cancellationToken));

             return rows is 1;
         }
         catch (SqliteException ex) when (ex.SqliteErrorCode is 19) // SQLITE_CONSTRAINT
         {
             return false;
         }
     }

